const https = require('https');
async function getChartInfo(userId) {
  return new Promise((resolve, reject) => {
    const url = 'https://scholar.google.com/citations?user=' + userId + '&hl=en';
    const options = { headers: { 'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36' }};
    https.get(url, options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        // Find the chart section and extract years + counts
        const chartIdx = data.indexOf('gsc_g_xtl');
        if (chartIdx === -1) { resolve(null); return; }
        const chartSection = data.substring(chartIdx, chartIdx + 5000);
        // Extract years
        const yearMatches = chartSection.match(/\b(20\d\d)\b/g);
        const years = yearMatches ? [...new Set(yearMatches)].filter(y => parseInt(y) >= 2000 && parseInt(y) <= 2026) : [];
        // Extract counts from gsc_g_a
        const re = /gsc_g_a[^>]*>(\d+)/g;
        let m;
        const counts = [];
        while ((m = re.exec(chartSection)) !== null) counts.push(parseInt(m[1]));
        resolve({years, counts});
      });
    }).on('error', reject);
  });
}

async function main() {
  const authors = [
    {name: 'Damien Ernst', id: '91ZxYSsAAAAJ'},
    {name: 'Vincent Francois-Lavet', id: 'n12uNYcAAAAJ'},
    {name: 'Guillaume Rabusseau', id: 't2i4V4EAAAAJ'},
    {name: 'Raphael Fonteneau', id: '0Z_y7GwAAAAJ'}
  ];

