        if (idx >= 0 && idx < info.counts.length) {
          console.log('2019 citations: ' + info.counts[idx]);
        }
        console.log('');
      }
    } catch(e) {
      console.log(a.name + ': ERROR ' + e.message);
    }
  }
}
main();
